class Solution {
    using ll = long long;
    using i128 = __int128_t;

    struct Line {
        ll m, b;
        int cnt;

        Line(ll slope, ll intercept, int count)
            : m(slope), b(intercept), cnt(count) {}
    };

    vector<ll> pref;
    int n;

    static ll value(const Line& line, ll x) {
        return line.m * x + line.b;
    }

    // Prefer lower cost; on ties prefer more partitions.
    static bool better(const Line& a,
                       const Line& b, ll x) {
        ll va = value(a, x);
        ll vb = value(b, x);

        if (va != vb)
            return va < vb;

        return a.cnt > b.cnt;
    }

    // Slopes are strictly decreasing.
    // Check whether b is unnecessary between a and c.
    static bool redundant(const Line& a,
                          const Line& b,
                          const Line& c) {
        return (i128)(b.b - a.b) * (b.m - c.m)
             > (i128)(c.b - b.b) * (a.m - b.m);
    }

    pair<ll, int> solve(ll penalty) {
        vector<Line> hull;
        hull.reserve(n + 1);

        hull.emplace_back(0, 0, 0);

        int head = 0;
        ll dp = 0;
        int count = 0;

        for (int i = 1; i <= n; ++i) {
            ll x = pref[i];

            // Prefix sums increase, so query pointer
            // moves only forward.
            while (head + 1 < (int)hull.size() &&
                   better(hull[head + 1],
                          hull[head], x)) {
                ++head;
            }

            const Line& best = hull[head];

            dp = x * x + x
               + value(best, x)
               + 2 * penalty;

            count = best.cnt + 1;

            Line next(
                -2 * x,
                dp + x * x - x,
                count
            );

            // Remove lines that will never be optimal.
            while (hull.size() >= 2 &&
                   redundant(
                       hull[hull.size() - 2],
                       hull[hull.size() - 1],
                       next)) {
                hull.pop_back();
            }

            hull.push_back(next);

            if (head >= (int)hull.size())
                head = (int)hull.size() - 1;
        }

        return {dp, count};
    }

public:
    long long minPartitionScore(vector<int>& nums, int k) {
        n = (int)nums.size();

        pref.assign(n + 1, 0);

        for (int i = 0; i < n; ++i)
            pref[i + 1] = pref[i] + nums[i];

        ll total = pref[n];

        ll low = 0;
        ll high = total * (total + 1) / 2;

        while (low < high) {
            ll mid = low + (high - low + 1) / 2;

            pair<ll, int> result = solve(mid);

            if (result.second >= k)
                low = mid;
            else
                high = mid - 1;
        }

        pair<ll, int> result = solve(low);

        return result.first / 2 - low * k;
    }
};
